def transform(grid):
    # The colored crossing points mark the entries of the reduced grid.
    # Rows and columns containing long uninterrupted divider stripes are the
    # lattice lines; their intersections give the output entries.
    h, w = len(grid), len(grid[0])

    row_lines = []
    for r, row in enumerate(grid):
        if len(set(row)) <= 2 and max(row.count(c) for c in set(row)) >= w - 2:
            row_lines.append(r)

    col_lines = []
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) <= 2 and max(vals.count(v) for v in set(vals)) >= h - 2:
            col_lines.append(c)

    # Extract the marker colors at intersections of the dominant periodic lines.
    if row_lines and col_lines:
        return [[grid[r][c] for c in col_lines] for r in row_lines]

    return [[grid[0][0]]]
