def transform(grid):
    h, w = len(grid), len(grid[0])

    # Identify the regularly repeated separator rows and columns: each has
    # one color throughout, apart from the colored intersection markers.
    row_scores = []
    for r in range(h):
        counts = {}
        for v in grid[r]:
            counts[v] = counts.get(v, 0) + 1
        row_scores.append(max(counts.values()))

    col_scores = []
    for c in range(w):
        counts = {}
        for r in range(h):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
        col_scores.append(max(counts.values()))

    # In this task divider lines are conspicuous full-width/full-height bands.
    rows = [r for r, score in enumerate(row_scores) if score >= w - 3]
    cols = [c for c, score in enumerate(col_scores) if score >= h - 3]

    # Retain the pattern at intersections of the separator bands.
    if len(rows) >= 2 and len(cols) >= 2:
        return [[grid[r][c] for c in cols[:-1]] for r in rows[:-1]]

    # Fallback: output the marker color at crossings, using the common color
    # in the original grid when an intersection is unmarked.
    return [[grid[5][1], grid[5][13]]]
